/**
 * @title A sidebar with collapsible submenus and search
 * @description Search on top; each section opens with a plus and closes with a minus. Only the section you're in starts open.
 * @route /docs
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { AppSidebar } from "@/components/app-sidebar";
import { SiteHeader } from "@/components/site-header";
import { PagePlaceholder } from "@/components/page-placeholder";

export default function Page() {
  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Building your application", href: "#" }, { label: "Data fetching" }]} />
        <PagePlaceholder title="Data fetching" />
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { Minus, Plus } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarGroup, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarMenuSub,
  SidebarMenuSubButton, SidebarMenuSubItem, SidebarRail, useDisclosure,
} from "@/components/ui/sidebar";
import { BrandHeader } from "@/components/brand-header";
import { docsNav } from "@/components/docs-nav";
import { SearchForm } from "@/components/search-form";

type Section = (typeof docsNav)[number];

function NavSection({ section }: { section: Section }) {
  const d = useDisclosure(section.items.some((i) => "isActive" in i && i.isActive));
  return (
    <SidebarMenuItem>
      <SidebarMenuButton {...d.triggerProps} size="sm" className="text-label-medium text-fg-primary">
        <span className="flex-1">{section.title}</span>
        <Icon name={d.open ? Minus : Plus} size={16} className="text-icon-secondary" />
      </SidebarMenuButton>
      <SidebarMenuSub {...d.contentProps}>
        {section.items.map((item) => (
          <SidebarMenuSubItem key={item.title}>
            <SidebarMenuSubButton href={item.url} isActive={"isActive" in item && item.isActive}><span>{item.title}</span></SidebarMenuSubButton>
          </SidebarMenuSubItem>
        ))}
      </SidebarMenuSub>
    </SidebarMenuItem>
  );
}

export function AppSidebar() {
  return (
    <Sidebar label="Documentation">
      <SidebarHeader>
        <BrandHeader />
        <SearchForm />
      </SidebarHeader>
      <SidebarContent>
        <SidebarGroup>
          <nav aria-label="Documentation">
            <SidebarMenu>{docsNav.map((s) => <NavSection key={s.title} section={s} />)}</SidebarMenu>
          </nav>
        </SidebarGroup>
      </SidebarContent>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { GalleryVerticalEnd, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Logo, product name and a second line (plan or version) at the top of the sidebar. Links home. */
export function BrandHeader({ name = "Acme Docs", detail = "v4.0.0", logo = GalleryVerticalEnd }: { name?: string; detail?: string; logo?: LucideIcon }) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="lg" tooltip={name}>
          <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={logo} size={16} /></span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-label-medium text-fg-primary">{name}</span>
            <span className="truncate text-caption-default">{detail}</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

/** Sample navigation for the documentation-style sidebars. Replace with your own pages. */
export const docsNav = [
  { title: "Getting started", url: "#", items: [{ title: "Installation", url: "#" }, { title: "Project structure", url: "#" }] },
  {
    title: "Building your application",
    url: "#",
    items: [
      { title: "Routing", url: "#" }, { title: "Data fetching", url: "#", isActive: true }, { title: "Rendering", url: "#" },
      { title: "Caching", url: "#" }, { title: "Styling", url: "#" }, { title: "Optimizing", url: "#" }, { title: "Configuring", url: "#" },
      { title: "Testing", url: "#" }, { title: "Authentication", url: "#" }, { title: "Deploying", url: "#" }, { title: "Upgrading", url: "#" },
    ],
  },
  { title: "API reference", url: "#", items: [{ title: "Components", url: "#" }, { title: "File conventions", url: "#" }, { title: "Functions", url: "#" }, { title: "Configuration options", url: "#" }, { title: "CLI", url: "#" }] },
  { title: "Architecture", url: "#", items: [{ title: "Accessibility", url: "#" }, { title: "Fast refresh", url: "#" }, { title: "Compiler", url: "#" }, { title: "Supported browsers", url: "#" }] },
  { title: "Community", url: "#", items: [{ title: "Contribution guide", url: "#" }] },
];
export const docsVersions = ["4.0.0", "3.2.0", "3.1.0"];

"use client";
import { useId } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarInput } from "@/components/ui/sidebar";

/** A search box for the sidebar header. */
export function SearchForm({ placeholder = "Search the docs…", className }: { placeholder?: string; className?: string }) {
  const id = useId();
  return (
    <form role="search" className={className} onSubmit={(e) => e.preventDefault()}>
      <label htmlFor={id} className="sr-only">Search</label>
      <div className="relative">
        <Icon name="search" size={16} className="pointer-events-none absolute start-2.5 top-1/2 -translate-y-1/2 text-icon-secondary" />
        <SidebarInput id={id} type="search" placeholder={placeholder} className="ps-8" />
      </div>
    </form>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

/** Stand-in content for a page. Replace it with your own. */
export function PagePlaceholder({ title }: { title: string }) {
  return (
    <div className="flex flex-1 flex-col gap-4 p-4 md:p-6">
      <h1 className="text-heading-h2">{title}</h1>
      <div aria-hidden className="grid gap-4 md:grid-cols-3">
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
        <div className="aspect-video rounded-container bg-surface-subtle" />
      </div>
      <div aria-hidden className="min-h-96 flex-1 rounded-container bg-surface-subtle" />
    </div>
  );
}
